{
  "findings": [
    {
      "check_id": "CKV_GCP_102",
      "title": "Pub/Sub Topic lacks Customer-Managed Encryption Key (CMEK)",
      "resource": "google_pubsub_topic.notification_queue",
      "severity": "MEDIUM",
      "explanation": "The Pub/Sub topic uses Google-managed encryption keys by default. For production environments handling sensitive data like insurance claims, using a Customer-Managed Encryption Key (CMEK) via KMS provides better control over key rotation and access management."
    }
  ],
  "patched_code": "resource \"google_pubsub_topic\" \"notification_queue\" {\n  name = \"insurance-claims-processing-platform-pubsub-notifications\"\n  labels = {\n    environment = \"production\"\n    component   = \"notifications\"\n  }\n\n  # Note: In a real implementation, you must define or reference a valid KMS CryptoKey.\n  # This block demonstrates the required configuration for CMEK compliance.\n  # Replace 'projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key' with your actual KMS key resource ID.\n  kms_key_name = \"projects/my-project/locations/us-central1/keyRings/my-keyring/cryptoKeys/my-key\"\n}",
  "fix_summary": "Added the `kms_key_name` attribute to the Pub/Sub topic to enforce Customer-Managed Encryption Keys (CMEK), replacing the default Google-managed encryption. A placeholder KMS key path was included as a comment/guidance since no specific KMS resource was defined in the original file; users must replace this with their actual KMS CryptoKey ID."
}
